TEXT_LIMIT='Bounded lexical/structural source-text observation only, not semantic call-graph/SQL/schema/WPF/renderer verification or whole-feature coverage. Application code is not executed.'
def evidence(*pairs):return ';'.join(f'{p}:{a}-{b}' for p,a,b in pairs)
def illustration(title,findings,inputs,observed,reference,diff,refs):
    assert (observed!=reference) is diff,title
    ILL.append(dict(id=f'ALG7B6-{len(ILL)+1:02d}',title=title,finding_ids=findings,hand_selected_inputs=inputs,manual_observation_model=observed,independent_reference=reference,difference_expected=diff,illustration_assertions_passed=True,evidence=refs,source_application_executed=False,limit=LIMIT))
def span(path,a,b):
    lines=(ROOT/path).read_text(encoding='utf-8-sig').splitlines();assert 1<=a<=b<=len(lines)
    text='\n'.join(lines[a-1:b]);READS[(path,a,b)]=dict(path=path,start=a,end=b,selected_text_sha256=hashlib.sha256(text.encode()).hexdigest())
    return text
def literal(title,findings,pairs,predicate,description):
    texts=[span(*x) for x in pairs];ok=bool(predicate(texts));assert ok,title
    ST.append(dict(id=f'ST7B6-{len(ST)+1:02d}',title=title,finding_ids=findings,documented_observation=description,documented_text_observation_matches=ok,evidence=evidence(*pairs),source_application_executed=False,limit=TEXT_LIMIT))

