    illustration('Selecting a user changes a control, not an absent predicate','P7-080',dict(rows_users=['A','B'],user_control='A',all_users=False,SQL_user_predicate=False),dict(eligible_users=['A','B']),dict(required_users=['A']),True,evidence((PO,166,199),(PO,351,368),(PX,238,250)))
